import { headers } from "next/headers";
import { getSeoDataByPageUrl } from "../admin/dashboard/seo/actions";

export default async function SeoMetadata() {
  const headersList = await headers();
  const pathname = headersList.get("x-pathname") || "/";

  let seoData = null;
  try {
    seoData = await getSeoDataByPageUrl(pathname);
  } catch (error) {
    console.error("Failed to fetch SEO data:", error);
  }

  const title =
    seoData?.title ||
    "Premier Web Design & Development Agency in Dubai | WD Agency";
  const description =
    seoData?.description ||
    "Transform your online presence with our top-rated web design and development services in Dubai. With 12+ years of experience, 50+ expert developers, and over 750 successful projects, we deliver scalable, responsive, and SEO-friendly websites that drive business growth. Get a custom quote today!";

  // Prepare the script content
  let scriptContent = null;
  if (seoData?.script) {
    const isJson = (str) => {
      try {
        JSON.parse(str);
        return true;
      } catch (e) {
        return false;
      }
    };

    if (isJson(seoData.script)) {
      scriptContent = (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: seoData.script }}
        />
      );
    } else {
      // If it contains tags, strip them and wrap in a script tag
      // This is a simple fallback for raw JS
      const cleanScript = seoData.script
        .replace(/<script[^>]*>/g, "")
        .replace(/<\/script>/g, "");
      scriptContent = (
        <script dangerouslySetInnerHTML={{ __html: cleanScript }} />
      );
    }
  }

  return (
    <>
      <title>{title}</title>
      <meta name="description" content={description} />
      {scriptContent}
    </>
  );
}
